import { useEffect, useState } from "react";
import Alert from "@mui/material/Alert";
import CircularProgress from "@mui/material/CircularProgress";
import Typography from "@mui/material/Typography";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";

import { getVisualizationData } from "../utils/api";
import type { VisualizationData } from "../utils/types";

const chartColors = [
  "#3FC0DF",
  "#5CE1E6",
  "#7AE7C7",
  "#F3C969",
  "#EF8354",
  "#EE6C4D",
];

function VisualizationsPage() {
  const [visualizationData, setVisualizationData] =
    useState<VisualizationData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function loadVisualizations() {
      try {
        const data = await getVisualizationData();
        setVisualizationData(data);
      } catch (err) {
        setError(
          err instanceof Error
            ? err.message
            : "Unable to load visualization data.",
        );
      } finally {
        setLoading(false);
      }
    }

    loadVisualizations();
  }, []);

  return (
    <div className="content-container">
      <div className="top-main-container">
        <Typography variant="h1" className="main-title">
          Data Visualizations
        </Typography>
      </div>

      <div className="visualizations-page">
        <div className="instructions visualizations-intro">
          <Typography variant="body1">
            These charts show the structure of the symptom dataset and help
            explain how the prediction model behaves.
          </Typography>
        </div>

        {loading && (
          <div className="loading-container">
            <CircularProgress />
            <Typography variant="body1">Loading charts...</Typography>
          </div>
        )}

        {error && (
          <div className="visualizations-alert">
            <Alert severity="error">{error}</Alert>
          </div>
        )}

        {visualizationData && (
          <>
            <div className="visualization-summary-grid">
              <div className="visualization-summary-card">
                <Typography variant="h4">
                  {visualizationData.summary.total_cases.toLocaleString()}
                </Typography>
                <Typography variant="body1">Total Cases</Typography>
              </div>
              <div className="visualization-summary-card">
                <Typography variant="h4">
                  {visualizationData.summary.total_diseases}
                </Typography>
                <Typography variant="body1">Disease Classes</Typography>
              </div>
              <div className="visualization-summary-card">
                <Typography variant="h4">
                  {visualizationData.summary.total_symptoms}
                </Typography>
                <Typography variant="body1">Symptom Features</Typography>
              </div>
              <div className="visualization-summary-card">
                <Typography variant="h4">
                  {visualizationData.summary.average_symptoms_per_case}
                </Typography>
                <Typography variant="body1">Average Symptoms per Case</Typography>
              </div>
            </div>

            <div className="visualization-grid">
              <section className="visualization-card">
                <Typography variant="h4">Top Symptom Frequency</Typography>
                <Typography variant="body1" className="visualization-caption">
                  Figure 1: The most common symptoms in the dataset, based on how
                  often each symptom appears across all cases.
                </Typography>
                <div className="chart-container">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart
                      data={visualizationData.top_symptoms}
                      layout="vertical"
                      margin={{ top: 8, right: 16, left: 80, bottom: 8 }}
                    >
                      <CartesianGrid strokeDasharray="3 3" stroke="#4f6479" />
                      <XAxis type="number" stroke="#020f1f" />
                      <YAxis
                        type="category"
                        dataKey="symptom"
                        width={140}
                        stroke="#020f1f"
                        tick={{ fontSize: 12 }}
                      />
                      <Tooltip />
                      <Bar dataKey="count" radius={[0, 6, 6, 0]}>
                        {visualizationData.top_symptoms.map((entry, index) => (
                          <Cell
                            key={`${entry.symptom}-${index}`}
                            fill={chartColors[index % chartColors.length]}
                          />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </section>

              <section className="visualization-card">
                <Typography variant="h4">Top Disease Distribution</Typography>
                <Typography variant="body1" className="visualization-caption">
                  Figure 2: The ten most frequent diseases in the dataset. This
                  helps show class balance and why some classes may be easier for
                  the model to learn.
                </Typography>
                <div className="chart-container">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart
                      data={visualizationData.disease_distribution}
                      margin={{ top: 8, right: 16, left: 8, bottom: 72 }}
                    >
                      <CartesianGrid strokeDasharray="3 3" stroke="#4f6479" />
                      <XAxis
                        dataKey="disease"
                        stroke="#020f1f"
                        angle={-35}
                        textAnchor="end"
                        interval={0}
                        height={90}
                        tick={{ fontSize: 12 }}
                      />
                      <YAxis stroke="#020f1f" />
                      <Tooltip />
                      <Bar dataKey="count" fill="#3FC0DF" radius={[6, 6, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </section>

              <section className="visualization-card visualization-card-wide">
                <Typography variant="h4">Symptom Count per Case</Typography>
                <Typography variant="body1" className="visualization-caption">
                  Figure 3: The number of symptoms present in each case. This
                  gives context for how simple or complex a typical patient record
                  is.
                </Typography>
                <div className="chart-container">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart
                      data={visualizationData.symptom_count_distribution}
                      margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                    >
                      <CartesianGrid strokeDasharray="3 3" stroke="#4f6479" />
                      <XAxis dataKey="symptomCount" stroke="#020f1f" />
                      <YAxis stroke="#020f1f" />
                      <Tooltip />
                      <Bar dataKey="cases" fill="#7AE7C7" radius={[6, 6, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </section>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

export default VisualizationsPage;
